output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are not allowed in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not move into a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "When entering a single-file shelf aisle from a wide aisle, the shopper must first leave the cart behind.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "wideToSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "wideAisle",
              "hasCart"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "wideToSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_aisle_mouth",
    "text": "A cart parked at the mouth of a single-file aisle must be retrieved before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "only_park_cart_in_wide_unobstructed_area",
    "text": "A shopper may only abandon a cart during an interaction in a wide unobstructed aisle area.",
    "abstraction": {
      "state_properties": {
        "wideUnobstructedParkingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "loseCartInInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "loseCartInInteraction",
          {
            "not": "wideUnobstructedParkingArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_ordinary_shelf_interactions",
    "text": "Interactions at ordinary shelf fronts require the shopper to have the cart, except inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "ordinaryShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "ordinaryShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_walking_without_cart_except_cart_free_zones",
    "text": "Moving without a cart is only acceptable at the cart pickup area, at cart-parking mouths, or inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartPickupArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartOptionalZone": {
          "or": [
            "cartPickupArea",
            "cartParkingMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartOptionalZone"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_visits_must_access_shelf",
    "text": "If a shopper enters a single-file shelf aisle on foot, the visit should include a shelf interaction there before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFootFromMouth": {
          "pre": {
            "and": [
              "MOVE",
              "cartParkingMouth",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "interactInSingleFileAisle": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFootFromMouth",
      "discharge": "interactInSingleFileAisle"
    }
  }
]
